<!--vbase-->
<template>
  <div class="container text-color-grey">
    <q-list bordered class="rounded-borders" v-if="model_list.length !== 0">
      <template v-for="(row, index) in model_list" :key="index">
        <q-expansion-item
          switch-toggle-side
          v-model="row['expanded']"
          :data-expanded="setModelState(row)"
        >
          <template v-slot:header>
            <q-item-section>
              <span class="text-weight-bolder text-h6"
                >{{ row['model_label'] }}
                <q-badge
                  transparent
                  align="middle"
                  v-if="row.is_default === true"
                  color="orange"
                >
                  {{ $t('default') }}
                </q-badge>
              </span>

              <div class="q-item__label q-item__label--caption text-caption">
                <q-icon
                  name="sell"
                  size="18px"
                  :color="
                    getLableCountForModel(row['model_name']) == '0'
                      ? 'grey-7'
                      : 'primary'
                  "
                  class="cursor-pointer"
                >
                </q-icon>
                {{ getLableCountForModel(row['model_name']) }} Label
              </div>
            </q-item-section>

            <q-item-section side v-if="false">
              <div class="row items-center">
                <label
                  @click.stop
                  class="active-toggle model-active-toggle q-mr-md"
                >
                  <input
                    disabled="true"
                    type="checkbox"
                    v-model="row.is_active"
                    @update:model-value="
                      (val: any) => {
                        handleActive(val, row);
                      }
                    "
                  />
                  <div class="slider"></div>
                </label>
                <template v-if="!row['is_deleted']">
                  <q-btn
                    flat
                    color="black"
                    class="float-right no-padding-left-right"
                    style="cursor: default"
                  >
                    <Icon icon="mdi:delete-off" width="20" height="20" />
                  </q-btn>
                </template>
                <template v-else>
                  <q-btn
                    flat
                    color="primary no-padding-left-right"
                    class="float-right"
                    @click="deleteRow()"
                  >
                    <q-icon name="delete" size="20px" />
                  </q-btn>
                </template>
              </div>
            </q-item-section>
          </template>
          <q-separator />
          <q-card>
            <q-card-section>
              <div class="row model-info ml-50">
                <div class="col-4">
                  <span class="text-weight-bolder">{{ $t('type') + ':' }}</span>
                  {{ row['model_type'] }}
                </div>
                <div class="col-3">
                  <span class="text-weight-bolder">{{
                    $t('first_page_only') + ':'
                  }}</span>
                  <span class="text-lowercase q-ml-sm">
                    {{
                      row['first_page_classification_only'] == false
                        ? $t('no')
                        : $t('yes')
                    }}
                  </span>
                </div>
                <div class="col-2">
                  <span class="text-weight-bolder">{{
                    $t('version') + ':'
                  }}</span>
                  {{ row['model_version'] }}
                </div>
              </div>

              <div class="row label-list ml-50">
                <div class="col-12">
                  <LabelsList :model="row['model_name']" />
                </div>
              </div>
            </q-card-section>
          </q-card>
        </q-expansion-item>
        <q-separator />
      </template>
    </q-list>

    <template v-if="!loading && model_list.length == 0">
      <div class="row">
        <div class="col-12 text-center">
          {{ $t('no_record_found') }}
        </div>
      </div>
    </template>
  </div>

  <q-dialog v-model="deleteConfirm" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('sure') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          data-cy="cancel"
          color="primary"
          v-close-popup
        />
        <q-btn
          flat
          :label="$t('delete')"
          data-cy="delete-popup"
          color="primary"
          v-close-popup
          @click="deleteLayout(selectedRowId)"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { aiModelsAndLabelsApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import LabelsList from 'src/pages/Settings/Components/ModelsAndLabels/LabelsList.vue';
import { useModelsLabelsStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    
    LabelsList,
  },
  data() {
    return {
      selectedRowId: ref(''),
      deleteConfirm: ref(false),
      selectedRowIndex: ref(0),
    };
  },
  mounted() {
    this.initView();
  },

  methods: {
    async initView() {
      try {
        this.loading = true;
        this.setDocType();
        await this.getAllModels();
        this.prepareColumns();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    setDocType() {
      this.doc_type = '';
      if (this.$route.query && this.$route.query.doc_type) {
        this.doc_type = String(this.$route.query.doc_type);
      }
    },

    async getAllModels() {
      const response = await this.getModels();
    },

    prepareColumns() {
      this.columns = [] as any;
      this.columns.push(
        Object.assign(
          {},
          {
            name: 'model_name',
            label: 'Name',
            field: 'model_name',
            align: 'left',
          },
        ),
      );

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'model_type',
            label: 'Type',
            field: 'model_type',
            align: 'left',
          },
        ),
      );

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'model_version',
            label: 'Version',
            field: 'model_version',
            align: 'left',
          },
        ),
      );

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'first_page_classification_only',
            label: 'Only First Page Classification',
            field: 'first_page_classification_only',
            align: 'left',
          },
        ),
      );
    },

    setModelState(row: any) {
      const count = this.getLableCountForModel(row['model_name']);
      if (count == '0' || this.doc_type == '' || row['triggered']) {
        return;
      }
      row['triggered'] = true;
      row['expanded'] = true;
    },

    deleteRow() {
      logInfo('deleteRow');
    },

    async handleActive(value: boolean, row: any) {
      const data: any = {
        id: row.id,
        is_active: String(value),
      };
      const response = await aiModelsAndLabelsApiService.updateModel(data);
    },
  },
  setup() {
    const model_labels_store = useModelsLabelsStore();
    const { setLabelsForModels, getLableCountForModel, getModels } =
      model_labels_store;
    const { model_list } = storeToRefs(model_labels_store);

    return {
      getModels,
      getLableCountForModel,
      setLabelsForModels,
      deleteLayout: async (model_name: string) => {
        // Delete layout logic
      },
      loading: ref(false),
      model_list,
      columns: ref([] as any),
      doc_type: ref(''),
    };
  },
});
</script>

<style scoped>
.model-item {
  border: 1px solid rgba(0, 0, 0, 0.12);
  font-weight: bold;
}
.model-active-toggle.active-toggle {
  height: 26px;
}

.model-active-toggle.active-toggle .slider:before {
  height: 24px;
}
</style>
