<!--vbase-->
<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{ $t('Edit Label') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width"></div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              clearable
              v-model="new_model['further_classification_model']"
              use-input
              :options="filteredModels"
              @filter="filteredModelsEvent"
              @update:model-value="new_model['associated_doc_type'] = ''"
              emit-value
              map-options
              :label="$t('Next Model')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['next_model_or_doc_type_required']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template
                      v-if="new_model['next_model_or_doc_type_required']"
                    >
                      {{ $t('next_model_or_doc_type_required') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              clearable
              v-model="new_model['associated_doc_type']"
              use-input
              :options="filterDocTypeList"
              @filter="filterDocTypeListEvent"
              @update:model-value="
                new_model['further_classification_model'] = ''
              "
              emit-value
              map-options
              :label="$t('document_type')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['next_model_or_doc_type_required']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template
                      v-if="new_model['next_model_or_doc_type_required']"
                    >
                      {{ $t('next_model_or_doc_type_required') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn class="bg-grey-3" :label="$t('cancel')" v-close-popup />

        <q-btn
          type="submit"
          color="primary"
          class="q-mr-sm"
          :label="$t('save')"
        />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDropdownStore, useModelsLabelsStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { aiModelsAndLabelsApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    model: {
      type: Object,
    },
  },

  components: {},
  data() {
    return {
      message: this.$t('only_characters_spaces'),
    };
  },
  setup() {
    let model = {} as { [k: string]: any };
    const dropdown_store = useDropdownStore();
    const filterDocTypeList: any = ref(dropdown_store.doc_type_list);
    const { doc_type_list } = storeToRefs(dropdown_store);

    const model_labels_store = useModelsLabelsStore();
    const { model_list } = storeToRefs(model_labels_store);

    return {
      model_list,
      models: ref([] as any),
      filteredModels: ref([] as any),
      filterDocTypeList,
      doc_type_list,
      new_model: ref(model),
      loading: ref(false),
      form_error: ref(''),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
    this.modelsDropdownList();
  },
  methods: {
    setNewModel() {
      if (this.model) {
        this.new_model = this.model;
      } else {
        this.new_model['further_classification_model'] = '';
        this.new_model['associated_doc_type'] = '';
      }

      this.resetErrors();
    },

    resetErrors() {
      this.new_model['next_model_or_doc_type_required'] = false;
    },

    modelsDropdownList() {
      this.model_list.forEach((row: any) => {
        const item = Object.assign(
          {},
          { value: row.model_name, label: row.model_name },
        );
        this.models.push(item);
        this.filteredModels.push(item);
      });
    },

    filteredModelsEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredModels = this.models;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredModels = this.models.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    filterDocTypeListEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterDocTypeList = this.doc_type_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterDocTypeList = this.doc_type_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      try {
        const data = this.setDataForApiRequest();
        let response;
        if (data.hasOwnProperty('id')) {
          response = await aiModelsAndLabelsApiService.updateLabel(data);
        } else {
          // response = await aiModelsAndLabelsApiService.createLabel(data);
          // if (!response.id) {
          //   throw {message: 'Failed to create new record'};
          // }
        }

        this.setNewModel();
        const event = new CustomEvent('record_saved', { detail: {} });
        document.dispatchEvent(event);
        notify.success(this.$t('operation_sucessfull'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    setDataForApiRequest() {
      let data = {} as dynamicObj;
      for (const [key, value] of Object.entries(this.new_model)) {
        data[key] = value || '';
      }

      return data;
    },

    validateRow(row: any) {
      let validate = true;
      this.resetErrors();

      if (!row['further_classification_model'] && !row['associated_doc_type']) {
        this.new_model['next_model_or_doc_type_required'] = true;
        notify.error(this.$t('next_model_or_doc_type_required'));
        validate = false;
      }

      return validate;
    },
  },
});
</script>

<style lang="scss" scoped></style>
