<!--vbase-->
<template>
  <div class="full-width">
    <div class="row q-mt-md">
      <div class="col-lg-12">
        <q-input
          dense
          v-model="search_labels"
          @keyup.enter="filterLabelsEvent"
          @update:model-value="filterLabelsEvent"
          :label="$t('search_labels')"
          outlined
        />
      </div>
    </div>

    <div class="row q-mb-md" v-if="search_labels">
      <div class="col-lg-12">
        <q-badge rounded color="primary">
          {{ 'Search By: ' + search_labels.toLowerCase() }}
          <q-icon
            name="close"
            color="white"
            class="q-ml-xs cursor-pointer"
            @click="removeFilter()"
          />
        </q-badge>
      </div>
    </div>

    <DocBitsTable
      :rows="rows"
      :columns="columns"
      row-key="id"
      :loading="loading"
      :features="{ sorting: false, pagination: false }"
      :no-data-label="$t('no_record_found')"
      table-height="400px"
      dense
    >
      <template #body-cell-associated_doc_type="{ row }">
        {{ docTypeLabel(row) }}
      </template>
      <template #body-cell-associated_sub_doc_type="{ row }">
        {{ subDocTypeLabel(row) }}
      </template>
      <template #body-cell-__actions__="{ row }">
        <q-btn
          color="grey"
          icon-right="edit"
          no-caps
          flat
          dense
          @click="editRow(row)"
        >
          <q-tooltip>{{ $t('edit') }}</q-tooltip>
        </q-btn>
      </template>
    </DocBitsTable>
  </div>

  <q-dialog v-model="deleteConfirm" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('sure') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          data-cy="cancel"
          color="primary"
          v-close-popup
        />
        <q-btn
          flat
          :label="$t('delete')"
          data-cy="delete-popup"
          color="primary"
          v-close-popup
          @click="deleteLayout()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog
    v-model="display_create_edit_dialog"
    persistent
    @keydown.esc="display_create_dialog = false"
  >
    <editCreateLabel :list_data="data" :model="edit_model"></editCreateLabel>
  </q-dialog>

  <q-inner-loading :showing="loading">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">

import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import docTypeLable from 'src/utils/docTypeLable';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { useModelsLabelsStore } from 'src/store/main';
import { aiModelsAndLabelsApiService } from 'src/services';
import { notify } from 'src/components/notifications/notify';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import editCreateLabel from 'src/pages/Settings/Components/ModelsAndLabels/editCreateLabel.vue';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, docTypeLable],
  components: {
    editCreateLabel,
    DocBitsTable,
  },
  props: {
    model: {
      type: String,
      default: '',
    },
  },
  watch: {
    model: {
      handler: function (newVal, oldVal) {
        this.setModelName();
        this.getLabels();
      },
    },
  },
  data() {
    return {
      selectedRowId: ref(''),
      deleteConfirm: ref(false),
      display_create_dialog: ref(false),
    };
  },
  mounted() {
    this.initView();
    document.addEventListener('record_saved', this.recordSaved);
  },
  unmounted: function () {
    document.removeEventListener('record_saved', this.recordSaved);
  },

  methods: {
    async initView() {
      try {
        this.loading = true;
        this.setDocType();
        this.setModelName();
        await this.getLabels();
        this.prepareColumns();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    setDocType() {
      this.doc_type = '';
      if (this.$route.query && this.$route.query.doc_type) {
        this.doc_type = String(this.$route.query.doc_type);
        this.search_labels = this.doc_type;
      }
    },

    setModelName() {
      this.model_name = this.model;
      if (this.$route.query && this.$route.query.model) {
        this.model_name = String(this.$route.query.model);
      }
    },
    async getLabels() {
      try {
        if (!this.model_name) {
          throw { message: 'Cannot load List.Model Name is missing' };
        }
        this.resetData();
        const response = await aiModelsAndLabelsApiService.getModelLabels(
          this.model_name,
        );

        if (response.success === false) {
          notify.error(response.message);
          throw { message: response.message };
        }

        this.label_list = response;
        this.prepareRows(response);
        this.setLabelCount();
      } catch (err) {
      } finally {
      }
    },

    prepareRows(data: any, is_filtered = false) {
      this.rows = [] as any;
      data.sort((a: any, b: any) => {
        return a.priority - b.priority;
      });

      this.rows = data;
      this.setLabelsForModels(this.model_name, this.rows.length);
      if (!is_filtered && this.doc_type != '') {
        this.filterLabelsEvent();
      }
    },

    resetData() {
      this.labels_count = 0;
      this.label_list = [];
    },

    setLabelCount() {
      if (!Array.isArray(this.label_list) || this.label_list.length == 0) {
        return;
      }
      this.labels_count = this.label_list.length;
      this.setLabelsForModels(this.model_name, this.labels_count);
    },

    prepareColumns() {
      this.columns = [] as any;

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'label_name',
            label: this.$t('name'),
            field: 'label_name',
            align: 'left',
          },
        ),
      );

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'further_classification_model',
            label: i18n.t('next_model'),
            field: 'further_classification_model',
            align: 'left',
          },
        ),
      );

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'associated_doc_type',
            label: this.$t('belegtyp'),
            field: 'associated_doc_type',
            align: 'left',
          },
        ),
      );

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'associated_sub_doc_type',
            label: this.$t('sub_doc_type'),
            field: 'associated_sub_doc_type',
            align: 'left',
          },
        ),
      );

      this.columns.push(
        Object.assign(
          {},
          {
            name: 'priority',
            label: i18n.t('priority'),
            field: 'priority',
            align: 'left',
          },
        ),
      );
    },

    editRow(row: any) {
      this.edit_model = row;
      this.display_create_edit_dialog = true;
    },

    recordSaved() {
      this.getLabels();
      this.display_create_edit_dialog = false;
    },

    filterLabelsEvent() {
      const excluded_columns = ['model_name'];
      const lowerSearch = this.search_labels.toLowerCase();
      let filteredRows = this.rows;

      if (!lowerSearch || lowerSearch === '') {
        this.prepareRows(filteredRows, true);
        return;
      }

      filteredRows = this.label_list.filter((row: any, i: number) => {
        let found = false;

        for (let [key, value] of Object.entries(row)) {
          let val = value as any;
          let original_val = val && val !== null ? val.toString() : '';
          val = original_val.toLowerCase();
          if (val.includes(lowerSearch) && !excluded_columns.includes(key)) {
            found = true;
            break;
          }
        }
        return found;
      });

      this.prepareRows(filteredRows, true);
    },

    removeFilter() {
      this.search_labels = '';
    },

    docTypeLabel(row: any) {
      return this.getDocTypeLabel({
        type: row.associated_doc_type || '',
        title: row.associated_doc_type_title || '',
        translation_key: row.associated_doc_type_translation_key || '',
      });
    },

    subDocTypeLabel(row: any) {
      return this.getDocTypeLabel({
        type: row.associated_sub_doc_type || '',
        title: row.associated_sub_doc_type_title || '',
        translation_key: row.associated_sub_doc_type_translation_key || '',
      });
    },
    deleteRow() {
      // Placeholder method for delete row functionality
      logInfo('deleteRow called');
    },
    deleteLayout() {
      // Placeholder method for delete layout functionality
      logInfo('deleteLayout called');
    },
  },
  setup() {
    const model_labels_store = useModelsLabelsStore();
    const { setLabelsForModels } = model_labels_store;
    return {
      setLabelsForModels,
      loading: ref(false),
      label_list: ref([] as any),
      columns: ref([] as any),
      rows: ref([] as any),
      filter: ref(''),
      model_name: ref(''),
      labels_count: ref(0),
      display_create_edit_dialog: ref(false),
      edit_model: ref({}),
      search_labels: ref(''),
      doc_type: ref(''),
    };
  },
});
</script>

<style scoped></style>
